class Employee:
    def __init__(self, salary):
        self._salary = salary

    @property
    def salary(self):
        return self._salary

    @salary.setter
    def salary(self, value):
        if value < 0:
            raise ValueError("Salary cannot be negative!")
        self._salary = value

emp = Employee(5000)
emp.salary = 6000  # Uses setter
print(emp.salary)  # Uses getter (6000)

